// Native tests for lib/report against golden vectors generated by the Rust
// codec (firmware/test/vectors.h). Pack output must match byte for byte;
// parse must give the same fields; malformed reports must fail with the same
// error kind Rust gives.

#include <string.h>
#include <unity.h>

#include "../vectors.h"
#include "report.h"

using detent::AppMessage;
using detent::Control;
using detent::ParseError;

static uint8_t out[DETENT_REPORT_LEN];

void setUp() { memset(out, 0xEE, sizeof out); }
void tearDown() {}

// --- pack: device to app, byte for byte ---

static void test_pack_hello() {
  const Control controls[] = {{1, DETENT_KIND_BUTTON}, {2, DETENT_KIND_BUTTON}, {9, DETENT_KIND_ENCODER}};
  TEST_ASSERT_TRUE(detent::pack_hello(out, 0, 0, 1, 2, DETENT_ENCODER_MODE_MAPPED, controls, 3));
  TEST_ASSERT_EQUAL_UINT8_ARRAY(DETENT_VEC_PACK_HELLO, out, DETENT_REPORT_LEN);
}

static void test_pack_hello_empty() {
  TEST_ASSERT_TRUE(detent::pack_hello(out, 255, 1, 0, 0, DETENT_ENCODER_MODE_VOLUME, nullptr, 0));
  TEST_ASSERT_EQUAL_UINT8_ARRAY(DETENT_VEC_PACK_HELLO_EMPTY, out, DETENT_REPORT_LEN);
}

static void test_pack_hello_max() {
  Control controls[DETENT_MAX_CONTROLS];
  for (uint8_t id = 0; id < DETENT_MAX_CONTROLS; id++) {
    controls[id] = {id, static_cast<uint8_t>(id % 2 == 0 ? DETENT_KIND_BUTTON : DETENT_KIND_ENCODER)};
  }
  TEST_ASSERT_TRUE(detent::pack_hello(out, 1, 2, 3, 4, DETENT_ENCODER_MODE_MENU, controls, DETENT_MAX_CONTROLS));
  TEST_ASSERT_EQUAL_UINT8_ARRAY(DETENT_VEC_PACK_HELLO_MAX, out, DETENT_REPORT_LEN);
}

static void test_pack_button() {
  TEST_ASSERT_TRUE(detent::pack_button(out, 9, 4, DETENT_ACTION_LONG_PRESS));
  TEST_ASSERT_EQUAL_UINT8_ARRAY(DETENT_VEC_PACK_BUTTON_LONG_PRESS, out, DETENT_REPORT_LEN);
}

static void test_pack_encoder() {
  TEST_ASSERT_TRUE(detent::pack_encoder(out, 10, 9, -3));
  TEST_ASSERT_EQUAL_UINT8_ARRAY(DETENT_VEC_PACK_ENCODER_NEGATIVE, out, DETENT_REPORT_LEN);
}

static void test_pack_menu_select() {
  detent::pack_menu_select(out, 11, 42);
  TEST_ASSERT_EQUAL_UINT8_ARRAY(DETENT_VEC_PACK_MENU_SELECT, out, DETENT_REPORT_LEN);
}

static void test_pack_heartbeat() {
  TEST_ASSERT_TRUE(detent::pack_heartbeat(out, 12, 0x01020304, DETENT_ENCODER_MODE_MENU));
  TEST_ASSERT_EQUAL_UINT8_ARRAY(DETENT_VEC_PACK_HEARTBEAT, out, DETENT_REPORT_LEN);
}

static void test_pack_refuses_invalid_messages() {
  Control many[DETENT_MAX_CONTROLS + 1];
  for (uint8_t id = 0; id <= DETENT_MAX_CONTROLS; id++) many[id] = {id, DETENT_KIND_BUTTON};
  TEST_ASSERT_FALSE(detent::pack_hello(out, 0, 0, 0, 0, 0, many, DETENT_MAX_CONTROLS + 1));
  const Control dup[] = {{3, DETENT_KIND_BUTTON}, {3, DETENT_KIND_ENCODER}};
  TEST_ASSERT_FALSE(detent::pack_hello(out, 0, 0, 0, 0, 0, dup, 2));
  const Control bad_kind[] = {{3, 7}};
  TEST_ASSERT_FALSE(detent::pack_hello(out, 0, 0, 0, 0, 0, bad_kind, 1));
  TEST_ASSERT_FALSE(detent::pack_hello(out, 0, 0, 0, 0, 3, nullptr, 0));
  TEST_ASSERT_FALSE(detent::pack_button(out, 0, 1, 0));
  TEST_ASSERT_FALSE(detent::pack_button(out, 0, 1, 4));
  TEST_ASSERT_FALSE(detent::pack_encoder(out, 0, 1, 0));
  TEST_ASSERT_FALSE(detent::pack_heartbeat(out, 0, 0, 3));
}

// --- parse: app to device ---

static AppMessage parse_ok(const uint8_t* vec) {
  AppMessage m;
  const ParseError err = detent::parse_app(vec, DETENT_REPORT_LEN, &m);
  TEST_ASSERT_EQUAL_STRING("None", detent::parse_error_name(err));
  return m;
}

static void test_parse_hello_ack() {
  const AppMessage m = parse_ok(DETENT_VEC_PARSE_HELLO_ACK);
  TEST_ASSERT_EQUAL_UINT8(DETENT_MSG_HELLO_ACK, m.type);
  TEST_ASSERT_EQUAL_UINT8(1, m.seq);
  TEST_ASSERT_TRUE(m.paired);
}

static void test_parse_menu_item() {
  const AppMessage m = parse_ok(DETENT_VEC_PARSE_MENU_ITEM);
  TEST_ASSERT_EQUAL_UINT8(DETENT_MSG_MENU, m.type);
  TEST_ASSERT_EQUAL_UINT8(2, m.seq);
  TEST_ASSERT_EQUAL_UINT8(3, m.menu_total);
  TEST_ASSERT_EQUAL_UINT8(1, m.menu_index);
  TEST_ASSERT_EQUAL_UINT8(42, m.menu_item);
  TEST_ASSERT_EQUAL_STRING("Mail", m.label);
}

static void test_parse_menu_clear() {
  const AppMessage m = parse_ok(DETENT_VEC_PARSE_MENU_CLEAR);
  TEST_ASSERT_EQUAL_UINT8(DETENT_MSG_MENU, m.type);
  TEST_ASSERT_EQUAL_UINT8(0, m.menu_total);
  TEST_ASSERT_EQUAL_STRING("", m.label);
}

static void test_parse_status() {
  TEST_ASSERT_EQUAL_STRING("Homepage", parse_ok(DETENT_VEC_PARSE_STATUS).status);
  const AppMessage empty = parse_ok(DETENT_VEC_PARSE_STATUS_EMPTY);
  TEST_ASSERT_EQUAL_UINT8(DETENT_MSG_STATUS, empty.type);
  TEST_ASSERT_EQUAL_STRING("", empty.status);
}

static void test_parse_request_hello() {
  const AppMessage m = parse_ok(DETENT_VEC_PARSE_REQUEST_HELLO);
  TEST_ASSERT_EQUAL_UINT8(DETENT_MSG_REQUEST_HELLO, m.type);
  TEST_ASSERT_EQUAL_UINT8(6, m.seq);
}

static void test_parse_test_inject() {
  const AppMessage m = parse_ok(DETENT_VEC_PARSE_TEST_INJECT);
  TEST_ASSERT_EQUAL_UINT8(DETENT_MSG_TEST_INJECT, m.type);
  TEST_ASSERT_EQUAL_UINT8(2, m.inject_count);
  TEST_ASSERT_EQUAL_UINT8(DETENT_MSG_BUTTON, m.inject[0].type);
  TEST_ASSERT_EQUAL_UINT8(4, m.inject[0].control);
  TEST_ASSERT_EQUAL_UINT8(DETENT_ACTION_DOWN, m.inject[0].value);
  TEST_ASSERT_EQUAL_UINT16(16, m.inject[0].delay_ms);
  TEST_ASSERT_EQUAL_UINT8(DETENT_MSG_ENCODER, m.inject[1].type);
  TEST_ASSERT_EQUAL_UINT8(9, m.inject[1].control);
  TEST_ASSERT_EQUAL_INT8(-3, static_cast<int8_t>(m.inject[1].value));
  TEST_ASSERT_EQUAL_UINT16(256, m.inject[1].delay_ms);
}

// --- reject: same verdict as Rust ---

static void test_rejects_match_rust() {
  for (size_t i = 0; i < DETENT_VEC_REJECT_COUNT; i++) {
    const DetentRejectVector& v = DETENT_VEC_REJECTS[i];
    AppMessage m;
    const ParseError err = detent::parse_app(v.bytes, DETENT_REPORT_LEN, &m);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(v.error, detent::parse_error_name(err), v.name);
  }
}

static void test_rejects_wrong_lengths() {
  uint8_t buf[DETENT_REPORT_LEN + 1] = {DETENT_PROTOCOL_VERSION, DETENT_MSG_REQUEST_HELLO};
  AppMessage m;
  TEST_ASSERT_EQUAL_STRING("ReportLength", detent::parse_error_name(detent::parse_app(buf, 0, &m)));
  TEST_ASSERT_EQUAL_STRING("ReportLength",
                           detent::parse_error_name(detent::parse_app(buf, DETENT_REPORT_LEN - 1, &m)));
  TEST_ASSERT_EQUAL_STRING("ReportLength",
                           detent::parse_error_name(detent::parse_app(buf, DETENT_REPORT_LEN + 1, &m)));
  TEST_ASSERT_EQUAL_STRING("None", detent::parse_error_name(detent::parse_app(buf, DETENT_REPORT_LEN, &m)));
}

int main() {
  UNITY_BEGIN();
  RUN_TEST(test_pack_hello);
  RUN_TEST(test_pack_hello_empty);
  RUN_TEST(test_pack_hello_max);
  RUN_TEST(test_pack_button);
  RUN_TEST(test_pack_encoder);
  RUN_TEST(test_pack_menu_select);
  RUN_TEST(test_pack_heartbeat);
  RUN_TEST(test_pack_refuses_invalid_messages);
  RUN_TEST(test_parse_hello_ack);
  RUN_TEST(test_parse_menu_item);
  RUN_TEST(test_parse_menu_clear);
  RUN_TEST(test_parse_status);
  RUN_TEST(test_parse_request_hello);
  RUN_TEST(test_parse_test_inject);
  RUN_TEST(test_rejects_match_rust);
  RUN_TEST(test_rejects_wrong_lengths);
  return UNITY_END();
}
